    wirbel: '<path d="M12 3a9 9 0 1 1-9 9 7 7 0 0 1 7-7 5 5 0 0 1 5 5 3 3 0 0 1-3 3 1.4 1.4 0 0 1-1.4-1.4"/>',
    diagramm: '<path d="M3.6 20.4h16.8"/><path d="M7.6 20.4V13"/><path d="M12 20.4V6.6"/><path d="M16.4 20.4v-9.4"/>',
